package com.bank.ledger;

import java.math.BigDecimal;
import java.util.logging.Logger;

class PendingLedger {
    private static final Logger log = Logger.getLogger(PendingLedger.class.getName());
    private TransactionNode head;
    private TransactionNode tail;

    // Append at end so the chain preserves arrival order.
    void append(BigDecimal amount) {
        TransactionNode node = new TransactionNode(amount);
        if (head == null) {
            head = tail = node;
        } else {
            tail.next = node;
            tail = node;
        }
    }

    // Traverse with a separate 'current' pointer; head stays put.
    void printAll() {
        TransactionNode current = head;
        while (current != null) {
            BigDecimal amt = current.amount;
            log.info(() -> "  Rs." + amt);
            current = current.next;        // advance
        }
    }

    // Traverse to accumulate a total; O(n) time, O(1) space.
    BigDecimal total() {
        BigDecimal sum = BigDecimal.ZERO;
        TransactionNode current = head;
        while (current != null) {
            sum = sum.add(current.amount);
            current = current.next;
        }
        return sum;
    }
}
